mapper.select:
SELECT s.id, s.doctor_id, s.department_id, d.real_name AS doctor_name, dp.name AS department_name, s.schedule_date, s.period, s.start_time, s.end_time, s.total_count, s.booked_count, (s.total_count - s.booked_count) AS remaining_count, s.fee, s.status, s.remark FROM doctor_schedule s JOIN doctor d ON d.id = s.doctor_id JOIN department dp ON dp.id = s.department_id WHERE s.status = 1 AND d.status = 1 AND d.deleted = 0 AND s.schedule_date >= CURRENT_DATE
AND s.department_id = #{departmentId}
AND s.doctor_id = #{doctorId}
AND s.schedule_date = #{scheduleDate}
AND s.period = #{period}
ORDER BY s.schedule_date, s.start_time
